document.addEventListener('DOMContentLoaded', () => { const messages = document.querySelectorAll('.alert'); if (messages.length > 0) { setTimeout(() => { messages.forEach(msg => { msg.style.transition = 'opacity 0.5s ease'; msg.style.opacity = '0'; setTimeout(() => msg.remove(), 500); }); }, 5000); } document.body.classList.remove('dark-mode'); localStorage.removeItem('theme'); });